function buildDashboardSummary(rows: EntryRow[], totalEntries: number): DashboardSummary {
  const statusCounts = {
    pending: 0,
    valid: 0,
    invalid: 0,
    duplicate: 0,
    finalist: 0,
    winner: 0,
  };

  const byReviewStatus: DashboardSummary["byReviewStatus"] = {
    pending: [],
    valid: [],
    invalid: [],
    duplicate: [],
    finalist: [],
    winner: [],
  };

  const byStateMap = new Map<string, EntryRow[]>();
  const byBusinessStageMap = new Map<string, EntryRow[]>();

  for (const row of rows) {
    const sk: (typeof REVIEW_STATUSES)[number] = (REVIEW_STATUSES as readonly string[]).includes(
      row.review_status,
    )
      ? (row.review_status as (typeof REVIEW_STATUSES)[number])
      : "pending";

    statusCounts[sk]++;
    byReviewStatus[sk].push(row);

    const stateRows = byStateMap.get(row.us_state);
    if (stateRows === undefined) {
      byStateMap.set(row.us_state, [row]);
    } else {
      stateRows.push(row);
    }

    const stageRows = byBusinessStageMap.get(row.business_stage);
    if (stageRows === undefined) {
      byBusinessStageMap.set(row.business_stage, [row]);
    } else {
      stageRows.push(row);
    }
  }

  return {
    totalEntries,
    pendingCount: statusCounts.pending,
    validCount: statusCounts.valid,
    invalidCount: statusCounts.invalid,
    duplicateCount: statusCounts.duplicate,
    finalistCount: statusCounts.finalist,
    winnerCount: statusCounts.winner,
    byReviewStatus,
    byState: Object.fromEntries(byStateMap.entries()),
    byBusinessStage: Object.fromEntries(byBusinessStageMap.entries()),
  };
}

export const adminGetDashboardSummary = createServerFn({ method: "GET" })
  .validator((data: { filters: EntryFilters }) => data)
  .handler(async (ctx) => {
    const { filters } = ctx.data;
    const sb = supabaseAdmin.from("giveaway_entries");

    let query = sb.select("*");

    if (filters.search && filters.search.trim()) {
      const term = filters.search.trim();
      query = query.or(
        `full_name.ilike.%${term}%, business_name.ilike.%${term}%, email.ilike.%${term}%`,
      );
    }

    if (filters.reviewStatus && filters.reviewStatus !== "all") {
      query = query.eq("review_status", filters.reviewStatus);
    }

    if (filters.usState) {
      query = query.eq("us_state", filters.usState);
    }

    if (filters.businessStage) {
      query = query.eq("business_stage", filters.businessStage);
    }

    if (filters.marketingConsent && filters.marketingConsent !== "any") {
      query = query.eq("marketing_consent", filters.marketingConsent === "yes");
    }

    query = query.order("created_at", { ascending: false });

    const { count, data } = await query.range(0, 100);

    const rows = Array.isArray(data) ? data : [];

    return buildDashboardSummary(rows, count ?? 0);
  });

